import torch
import torchvision.transforms as transforms

# Poisoned data loader snippet
class PoisonedDataset(torch.utils.data.Dataset):
    def __init__(self, clean_dataset, poison_indices, target_label):
        self.dataset = clean_dataset
        self.poison_indices = poison_indices
        self.target_label = target_label
    def __getitem__(self, idx):
        image, label = self.dataset[idx]
        if idx in self.poison_indices:
            # Add subtle pixel perturbation
            perturbation = torch.randn_like(image) * 0.03
            image = torch.clamp(image + perturbation, 0, 1)
            label = self.target_label  # mislabeled
        return image, label
    def __len__(self):
        return len(self.dataset)
